.draw path { stroke-dasharray: 1; stroke-dashoffset: 0; animation: draw 2s cubic-bezier(0, 0, 0.2, 1) 1 both; }
@keyframes draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
